module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] counter;
reg [9:0] accum_register;
reg valid_latch;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        accum_register <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
        valid_latch <= 1'b0;
    end else begin
        valid_out <= 1'b0; // default, will be set high when accumulation completes
        if (valid_in) begin
            accum_register <= accum_register + {2'b00, data_in};
            counter <= counter + 1;
            if (counter == 2'b11) begin
                data_out <= accum_register + {2'b00, data_in};
                valid_out <= 1'b1;
                counter <= 2'b00;
                accum_register <= 10'b0;
            end
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] counter;
reg [9:0] accum_register;
reg valid_latch;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        accum_register <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0; // Default to low, set high when ready
        if (valid_in) begin
            accum_register <= accum_register + data_in;
            if (counter == 2'b11) begin
                // After 4 inputs
                data_out <= accum_register + data_in; // Final sum
                valid_out <= 1'b1; // Signal output valid
                counter <= 2'b00; // Reset counter
                accum_register <= 10'b0; // Reset accumulator
            end else begin
                counter <= counter + 1;
                if (counter == 2'b10) begin
                    // Next input will complete the 4 inputs
                    // Keep accumulator until last input
                end
            end
        end
    end
end

endmodule

