module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

// Internal carry signals between the two 8-bit adders
wire carry_internal;

// Instantiate first 8-bit adder for least significant bits
adder_8bit adder_low (
    .a(a[7:0]),
    .b(b[7:0]),
    .Cin(Cin),
    .sum(y[7:0]),
    .Co(carry_internal)
);

// Instantiate second 8-bit adder for most significant bits
adder_8bit adder_high (
    .a(a[15:8]),
    .b(b[15:8]),
    .Cin(carry_internal),
    .sum(y[15:8]),
    .Co(Co)
);

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

// Internal carries between 8-bit adders
wire carry_internal_0;
wire carry_internal_1;

// Instantiate first 8-bit adder for lower bits
adder_8bit lower_adder (
    .a(a[7:0]),
    .b(b[7:0]),
    .Cin(Cin),
    .sum(y[7:0]),
    .Cout(carry_internal_0)
);

// Instantiate second 8-bit adder for higher bits
adder_8bit upper_adder (
    .a(a[15:8]),
    .b(b[15:8]),
