        .G(G_upper),
        .P(P_upper),
        .Cout(C32)
    );

    // Concatenate the sum parts
    assign S = {S_upper, S_lower};

    // Propagate signals for upper 16 bits
    assign P_upper = P_upper;
    assign G_upper = G_upper;

    // Propagate signals for lower 16 bits
    assign P_lower = P_lower;
    assign G_lower = G_lower;

endmodule

// 16-bit Carry-Lookahead Adder Module
module CLA_16bit(A, B, Cin, S, G, P, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] S;
    output [15:1] G;
    output [15:1] P;
    output Cout;

    wire [15:0] C; // Carry signals for bits 1 to 16

    genvar i;

    // Compute propagate and generate for each bit
    generate
        for (i = 1; i <= 15; i = i + 1) begin : gen_pg
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
        end
        // For bit 16
        assign P[16] = A[16] ^ B[16];
        assign G[16] = A[16] & B[16];
    endgenerate

    // Carry computation
    // C[1] = Cin
    assign C[1] = Cin;

    // For bits 2 to 16
    generate
        for (i = 2; i <= 16; i = i + 1) begin : carry_gen
            assign C[i] = G[i-1] | (P[i-1] & C[i-1]);
        end
    endgenerate

    // Compute sum bits
    generate
        for (i = 1; i <= 16; i = i + 1) begin : sum_gen
            assign S[i] = P[i] ^ C[i];
        end
    endgenerate

    // Final carry out
    assign Cout = G[16] | (P[16] & C[16]);

endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire C16; // carry from lower 16 bits to upper 16 bits

    // Internal propagate and generate signals for lower 16 bits
    wire [16:1] P_low, G_low;
    // Internal propagate and generate signals for upper 16 bits
    wire [16:1] P_high, G_high;

    // Wires for sum outputs from each 16-bit CLA
    wire [16:1] S_low, S_high;

    // Instantiate 16-bit CLA for lower 16 bits
    // Propagate and generate signals for lower 16 bits
    genvar i;
    generate
        for (i = 1; i <= 16; i = i + 1) begin : gen_low
            assign P_low[i] = A[i] ^ B[i];
            assign G_low[i] = A[i] & B[i];
        end
    endgenerate

    // Compute carry signals for lower 16 bits
    // C[0] is assumed 0 for initial carry in
    wire [16:0] C0; // carry signals for bits 0 to 16
    assign C0[1] = 1'b0; // initial carry-in is 0
    generate
        for (i = 1; i <= 16; i = i + 1) begin : carry_gen_low
            // Carry for bit i+1:
            // C[i+1] = G[i] | (P[i] & C[i])
            // We'll generate these combinationally
            // For clarity, assign intermediate signals
            // but as per constraints, no break statements or procedural code
        end
    endgenerate

    // Instead, implement carry lookahead logic explicitly:
    // For each bit, compute carry using known formulas
    // To avoid complexity, implement carry for bit 1 to 16
    // Using the standard CLA equations:
    // C[1] = G_low[1] | (P_low[1] & C0[1]) = G_low[1] since C0[1]=0
    // For subsequent bits:
    // C[i+1] = G_low[i] | (P_low[i] & C[i])

    // For simplicity, implement carry for each bit explicitly
    wire [16:1] C_low_wire; // carry signals for bits 1 to 16
    assign C_low_wire[1] = G_low[1] | (P_low[1] & C0[1]);
    generate
        for (i = 2; i <= 16; i = i + 1) begin : carry_chain_low
            assign C_low_wire[i] = G_low[i] | (P_low[i] & C_low_wire[i-1]);
        end
    endgenerate

    // Compute sum for lower 16 bits
    generate
        for (i = 1; i <= 16; i = i + 1) begin : sum_low
            assign S_low[i] = P_low[i] ^ C_low_wire[i];
        end
    endgenerate

    assign C16 = C_low_wire[16]; // carry out from lower 16 bits

    // Instantiate 16-bit CLA for upper 16 bits
    wire [16:1] P_high, G_high;
    wire [16:1] S_high;

    generate
        for (i = 17; i <= 32; i = i + 1) begin : gen_high
            assign P_high[i-16] = A[i] ^ B[i];
            assign G_high[i-16] = A[i] & B[i];
        end
    endgenerate

    // Carry signals for upper 16 bits
    wire [16:1] C_high_wire;
    // C[17] is C16 from lower bits
    assign C_high_wire[1] = G_high[1] | (P_high[1] & C16);
    generate
        for (i = 2; i <= 16; i = i + 1) begin : carry_chain_high
            assign C_high_wire[i] = G_high[i] | (P_high[i] & C_high_wire[i-1]);
        end
    endgenerate

    // Sum for upper 16 bits
    generate
        for (i = 17; i <= 32; i = i + 1) begin : sum_high
            assign S[i] = P_high[i-16] ^ C_high_wire[i-16];
        end
    endgenerate

    assign C32 = C_high_wire[16]; // final carry-out

    // Concatenate lower and upper sums
    assign S[16:1] = S_low;
    assign S[32:17] = S_high;

endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire C16; // Carry from lower 16-bit CLA to upper 16-bit CLA

    // Propagate and generate signals for lower 16 bits
    wire [16:1] P_low, G_low;
    // Propagate and generate signals for upper 16 bits
    wire [16:1] P_high, G_high;

    // Instantiate lower 16-bit CLA
    CLA16bit lower_cla (
        .A(A[16:1]),
        .B(B[16:1]),
        .Cin(1'b0),
        .Sum(S[16:1]),
        .P(P_low),
        .G(G_low),
        .Cout(C16)
    );

    // Instantiate upper 16-bit CLA
    CLA16bit upper_cla (
        .A(A[32:17]),
        .B(B[32:17]),
        .Cin(C16),
        .Sum(S[32:17]),
        .P(P_high),
        .G(G_high),
        .Cout(C32)
    );
endmodule

// 16-bit Carry-Lookahead Adder Module
module CLA16bit(A, B, Cin, Sum, P, G, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] Sum;
    output [16:1] P;
    output [16:1] G;
    output Cout;

    wire [16:0] C; // Carry signals, C[0]=Cin

    assign C[0] = Cin;

    genvar i;
    generate
        for (i=1; i<=16; i=i+1) begin : cla_loop
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];

            assign C[i] = G[i] | (P[i] & C[i-1]);
            assign Sum[i] = P[i] ^ C[i-1];
        end
    endgenerate

    assign Cout = C[16];
endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
