    // Compute carry for lower 16 bits
    wire [16:0] C_low; // C_low[0] is initial carry-in (zero)
    assign C_low[0] = 1'b0; // No initial carry-in
    generate
        for (i = 1; i <= 16; i = i + 1) begin : carry_gen_low
            assign C_low[i] = G_low[i] | (P_low[i] & C_low[i-1]);
        end
    endgenerate

    // Sum for lower 16 bits
    generate
        for (i = 1; i <= 16; i = i + 1) begin : sum_low
            assign S_low[i] = P_low[i] ^ C_low[i-1];
        end
    endgenerate

    assign C16 = C_low[16];

    // Instantiate upper 16-bit CLA
    // Propagate and generate signals
    generate
        for (i = 1; i <= 16; i = i + 1) begin : high_bits
            assign P_high[i] = A[16 + i] ^ B[16 + i];
            assign G_high[i] = A[16 + i] & B[16 + i];
        end
    endgenerate

    // Compute carry for upper 16 bits
    wire [16:0] C_high; // C_high[0] is C16
    assign C_high[0] = C16;
    generate
        for (i = 1; i <= 16; i = i + 1) begin : carry_gen_high
            assign C_high[i] = G_high[i] | (P_high[i] & C_high[i-1]);
