module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Number of pipeline stages
localparam NUM_STAGES = (DATA_WIDTH + STG_WIDTH -1)/STG_WIDTH;

// Internal signals for pipeline registers
reg [DATA_WIDTH-1:0] adda_reg [0:NUM_STAGES];
reg [DATA_WIDTH-1:0] addb_reg [0:NUM_STAGES];
reg i_en_reg [0:NUM_STAGES];

reg [DATA_WIDTH:0] sum_reg [0:NUM_STAGES];
reg carry_reg [0:NUM_STAGES]; // carry between stages

reg o_en_reg [0:NUM_STAGES]; // pipeline enable

integer i;

// Initialize or reset pipeline registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i=0; i<=NUM_STAGES; i=i+1) begin
            adda_reg[i] <= 0;
            addb_reg[i] <= 0;
            i_en_reg[i] <= 0;
            sum_reg[i] <= 0;
            carry_reg[i] <= 0;
            o_en_reg[i] <= 0;
        end
        o_en <= 0;
    end else begin
        // Input stage
        adda_reg[0] <= adda;
        addb_reg[0] <= addb;
        i_en_reg[0] <= i_en;
        sum_reg[0] <= 0;
        carry_reg[0] <= 0;
        o_en_reg[0] <= 0;

        // Pipeline stages
        for (i=1; i<=NUM_STAGES; i=i+1) begin
            // Determine segment boundaries
            wire [STG_WIDTH-1:0] a_segment, b_segment;
            wire [STG_WIDTH:0] partial_sum;
            wire carry_out;

            // For last stage, may have less than STG_WIDTH bits
            localparam integer start_bit = (i-1)*STG_WIDTH;
            localparam integer end_bit = ( (start_bit + STG_WIDTH -1) < DATA_WIDTH ) ? (start_bit + STG_WIDTH -1) : (DATA_WIDTH -1);
            localparam integer width = end_bit - start_bit + 1;

            assign a_segment = adda_reg[i-1][end_bit:start_bit];
            assign b_segment = addb_reg[i-1][end_bit:start_bit];

            // Add segment with carry_in
            wire carry_in = carry_reg[i-1];

            assign partial_sum = {1'b0, a_segment} + {1'b0, b_segment} + carry_in;
            assign carry_out = partial_sum[width];

            // Register operands for next stage
            if (width < STG_WIDTH) begin
                // For last stage, assign only relevant bits
                assign sum_reg[i][end_bit:start_bit] = partial_sum[width-1:0];
            end else begin
                assign sum_reg[i][end_bit:start_bit] = partial_sum[width-1:0];
            end

            // Update pipeline registers
            if (width < STG_WIDTH) begin
                // For last stage, assign only bits
                for (integer j=start_bit; j<=end_bit; j=j+1) begin
                    sum_reg[i][j] <= partial_sum[j - start_bit];
                end
            end else begin
                sum_reg[i][end_bit:start_bit] <= partial_sum[width-1:0];
            end

            // Propagate operands and enable
            adda_reg[i] <= adda_reg[i-1];
            addb_reg[i] <= addb_reg[i-1];
            i_en_reg[i] <= i_en_reg[i-1];

            // Set sum for this stage
            sum_reg[i] <= (i==NUM_STAGES) ? {carry_out, a_segment + b_segment} : sum_reg[i];

            // Propagate carry
            carry_reg[i] <= carry_out;

            // Set output enable at last stage
            o_en_reg[i] <= (i == NUM_STAGES) ? i_en_reg[i-1] : 0;
        end
        // Output assignment
        o_en <= o_en_reg[NUM_STAGES];
    end
end

// Final result assignment
assign result = sum_reg[NUM_STAGES];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Number of pipeline stages
localparam NUM_STAGES = (DATA_WIDTH + STG_WIDTH - 1) / STG_WIDTH;

// Registers for pipeline stages
reg [DATA_WIDTH-1:0] adda_reg [0:NUM_STAGES];
reg [DATA_WIDTH-1:0] addb_reg [0:NUM_STAGES];
reg        en_reg   [0:NUM_STAGES];
reg [DATA_WIDTH:0] sum_reg [0:NUM_STAGES];
reg             carry_reg [0:NUM_STAGES];

// Initialize the first stage
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg[0] <= 0;
        addb_reg[0] <= 0;
        en_reg[0]  <= 0;
        sum_reg[0] <= 0;
        carry_reg[0] <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
            en_reg[0]  <= 1'b1;
            sum_reg[0] <= 0;
            carry_reg[0] <= 0;
        end else begin
            en_reg[0] <= 0;
        end
    end
end

// Generate pipeline stages
genvar stage;
generate
    for (stage = 1; stage <= NUM_STAGES; stage = stage + 1) begin : PIPELINE_STAGES
        localparam START_BIT = (stage - 1) * STG_WIDTH;
        localparam END_BIT = (stage * STG_WIDTH) - 1;
        localparam WIDTH = (END_BIT - START_BIT + 1);
        // Handle last stage width
        localparam ACTUAL_WIDTH = (END_BIT < DATA_WIDTH) ? WIDTH : (DATA_WIDTH - START_BIT);

        wire [ACTUAL_WIDTH-1:0] a_slice = adda_reg[stage-1][START_BIT +: ACTUAL_WIDTH];
        wire [ACTUAL_WIDTH-1:0] b_slice = addb_reg[stage-1][START_BIT +: ACTUAL_WIDTH];

        reg [ACTUAL_WIDTH:0] sum_stage;
        reg carry_out;

        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin
                adda_reg[stage] <= 0;
                addb_reg[stage] <= 0;
                en_reg[stage]  <= 0;
                sum_reg[stage] <= 0;
                carry_reg[stage] <= 0;
            end else if (en_reg[stage-1]) begin
                // Perform addition on this slice
                {carry_out, sum_stage} <= {1'b0, a_slice} + {1'b0, b_slice} + carry_reg[stage-1];
