        en_pipe <= {(NUM_STAGES+1){1'b0}};
        o_en <= 1'b0;
    end else begin
        // Input stage
        if (i_en) begin
            adda_pipe[0] <= adda;
            addb_pipe[0] <= addb;
            en_pipe[0] <= 1'b1;
        end else begin
            adda_pipe[0] <= adda_pipe[0];
            addb_pipe[0] <= addb_pipe[0];
            en_pipe[0] <= 1'b0;
        end
        sum_pipe[0] <= {1'b0, adda_pipe[0]} + {1'b0, addb_pipe[0]};

        // Pipeline stages
        for (i = 1; i <= NUM_STAGES; i = i + 1) begin
            adda_pipe[i] <= adda_pipe[i-1];
            addb_pipe[i] <= addb_pipe[i-1];
            en_pipe[i] <= en_pipe[i-1];
            sum_pipe[i] <= {1'b0, sum_pipe[i-1][DATA_WIDTH-1:0]} + (sum_pipe[i-1][DATA_WIDTH] ? {1'b0, addb_pipe[i-1]} + 1'b1 : 0);
        end

        // Output enable at last stage
        o_en <= en_pipe[NUM_STAGES];
    end
end

// Assign final result
assign result = sum_pipe[NUM_STAGES];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Number of pipeline stages
localparam NUM_STAGES = (DATA_WIDTH + STG_WIDTH - 1) / STG_WIDTH;

// Internal signals for pipeline registers
reg [DATA_WIDTH-1:0] adda_pipe [0:NUM_STAGES];
reg [DATA_WIDTH-1:0] addb_pipe [0:NUM_STAGES];
reg        en_pipe [0:NUM_STAGES];
reg [DATA_WIDTH:0] sum_pipe [0:NUM_STAGES]; // To hold partial sums including carry

integer i;

// Initialize pipeline registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i <= NUM_STAGES; i = i + 1) begin
            adda_pipe[i] <= 0;
            addb_pipe[i] <= 0;
            en_pipe[i] <= 0;
            sum_pipe[i] <= 0;
        end
        o_en <= 0;
    end else begin
        // Input stage
        if (i_en) begin
            adda_pipe[0] <= adda;
            addb_pipe[0] <= addb;
            en_pipe[0] <= 1;
        end else begin
            adda_pipe[0] <= adda;
            addb_pipe[0] <= addb;
            en_pipe[0] <= 0;
        end
        // Pipeline stages
        for (i = 1; i <= NUM_STAGES; i = i + 1) begin
            adda_pipe[i] <= adda_pipe[i-1];
            addb_pipe[i] <= addb_pipe[i-1];
            en_pipe[i] <= en_pipe[i-1];
        end
        // Perform segmented addition
        // Initialize carry
        reg carry;
        reg [STG_WIDTH-1:0] a_part, b_part;
        reg [STG_WIDTH:0] sum_part;
        reg [DATA_WIDTH:0] total_sum;
        carry = 0;
        total_sum = 0;

        for (i = 0; i < NUM_STAGES; i = i + 1) begin
            a_part = adda_pipe[i][(i*STG_WIDTH) +: STG_WIDTH];
            b_part = addb_pipe[i][(i*STG_WIDTH) +: STG_WIDTH];

            sum_part = {1'b0, a_part} + {1'b0, b_part} + carry;
            sum_pipe[i] <= {sum_part[STG_WIDTH-1:0], {DATA_WIDTH - (i+1)*STG_WIDTH{1'b0}}};
            carry = sum_part[STG_WIDTH];
        end

        // Final stage sum
        // For the last segment, handle remaining bits
        a_part = adda_pipe[NUM_STAGES][(NUM_STAGES*STG_WIDTH) +: STG_WIDTH];
        b_part = addb_pipe[NUM_STAGES][(NUM_STAGES*STG_WIDTH) +: STG_WIDTH];

        sum_part = {1'b0, a_part} + {1'b0, b_part} + carry;
        sum_pipe[NUM_STAGES] <= sum_part;

        // Set output enable
        o_en <= en_pipe[NUM_STAGES];
    end
end

// Assign final result
assign result = sum_pipe[NUM_STAGES];

endmodule

