// Gray-coded pointers
reg [ADDR_WIDTH:0] wptr, rptr; // extra bit for full/empty detection
reg [ADDR_WIDTH:0] wptr_sync, rptr_sync; // synchronized versions

// Pointers from other domain (for comparison)
reg [ADDR_WIDTH:0] wptr_buff, rptr_buff;

