module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_reg;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_reg <= 1'b0;
		rise <= 1'b0;
		down <= 1'b0;
	end else begin
		// Detect rising edge
		if (a && !a_reg) begin
			rise <= 1'b1;
			down <= 1'b0;
		end
		// Detect falling edge
		else if (!a && a_reg) begin
			down <= 1'b1;
			rise <= 1'b0;
		end
		else begin
			rise <= 1'b0;
			down <= 1'b0;
		end
		a_reg <= a;
	end
end

endmodule

