module multi_16bit(
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

reg [15:0] areg;
reg [15:0] breg;
reg [31:0] yout_r;
reg [3:0] i;
reg done_r;

assign yout = yout_r;
assign done = done_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 4'd0;
        done_r <= 1'b0;
    end else begin
        if (start) begin
            if (i == 4'd0) begin
                i <= 4'd1; // start counting from 1 after load
            end else if (i < 4'd17) begin
                i <= i + 1;
            end
            if (i == 4'd0) begin
                // Load inputs at start
                areg <= ain;
                breg <= bin;
                yout_r <= 32'd0;
                done_r <= 1'b0;
            end
        end else begin
            if (i == 4'd0) begin
                // Idle state, wait for start
                i <= 4'd0;
                done_r <= 1'b0;
            end
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        areg <= 16'd0;
        breg <= 16'd0;
        yout_r <= 32'd0;
        done_r <= 1'b0;
    end else begin
        if (start && i != 4'd0 && i < 4'd17) begin
            // Perform shift-and-add
            if (i == 1) begin
                // First cycle: load inputs
                yout_r <= 32'd0;
            end else if (i > 1 && i <= 16) begin
                // Check the (i-2)th bit of areg
                if (areg[i-2]) begin
                    yout_r <= yout_r + (breg << (i-2));
                end
            end
            if (i == 16) begin
                // Multiplication done
                done_r <= 1'b1;
            end
        end
    end
end

endmodule

module multi_16bit(
    input clk,          // Chip clock signal.
    input rst_n,        // Active-low reset signal. Defined as 0 for chip reset; defined as 1 for reset signal inactive.
    input start,        // Chip enable signal. 
    input [15:0] ain,   // Input a (multiplicand) with a data width of 16 bits.
    input [15:0] bin,   // Input b (multiplier) with a data width of 16 bits.
    output [31:0] yout, // Product output with a data width of 32 bits.
    output done         // Chip output flag signal. Defined as 1 indicates multiplication operation completion.
);

reg [15:0] areg;
reg [15:0] breg;
reg [31:0] yout_r;
reg [4:0] i;          // 5 bits to count from 0 to 16
reg done_r;

assign yout = yout_r;
assign done = done_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 0;
        areg <= 0;
        breg <= 0;
        yout_r <= 0;
        done_r <= 0;
    end else begin
        // Manage shift count
        if (start) begin
            if (i == 0) begin
                i <= 1; // Start counting from 1 after load
            end
        end else begin
            if (i != 0 && i < 17) begin
                i <= i + 1;
            end
        end

        // Main multiplication process
        if (start && i == 0) begin
            areg <= ain;
            breg <= bin;
            yout_r <= 0;
            done_r <= 0;
        end else if (i > 0 && i <= 16) begin
            // Check the previous bit of areg to decide addition
            if (areg[i-1]) begin
                yout_r <= yout_r + (breg << (i-1));
            end
            // When i reaches 16, set done flag
            if (i == 16) begin
                done_r <= 1;
            end
        end
    end
end

endmodule

