module multi_booth_8bit (p, rdy, clk, reset, a, b);
    input clk, reset;
    input [7:0] a, b;
    output reg [15:0] p;
    output reg rdy;

    reg [15:0] multiplier;    // Holds sign-extended 'a'
    reg [15:0] multiplicand;  // Holds sign-extended 'b'
    reg [4:0]  ctr;           // Cycle counter (since 8 bits, 4 cycles for radix-4, but using 5 bits for safety)
    reg [15:0] temp;          // Temporary register for computation
    reg [1:0] booth_code;     // Booth encoding bits
    reg [15:0] m;             // Sign-extended multiplicand
    reg [15:0] q;             // Sign-extended multiplier

    // Initialize registers
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            p <= 16'b0;
            rdy <= 1'b0;
            multiplier <= 16'sd0;
            multiplicand <= 16'sd0;
            ctr <= 5'd0;
            m <= 16'sd0;
            q <= 16'sd0;
        end else begin
            if (ctr == 0) begin
                // Load sign-extended inputs at start
                multiplier <= {a[7], a} ; // Sign-extend 8-bit to 16-bit
                q <= {b[7], b};
                p <= 16'b0;
                m <= {b[7], b};
                rdy <= 1'b0;
                ctr <= 5'd8; // 8 cycles for 8 bits
            end else if (ctr > 0) begin
                // Booth encoding based on lowest two bits of multiplier
                booth_code <= {multiplier[1:0]};
                case (booth_code)
                    2'b01, 2'b10: begin
                        // Add multiplicand
                        p <= p + (m);
                    end
                    2'b11: begin
                        // Subtract multiplicand
                        p <= p - (m);
                    end
                    default: begin
                        // No operation (00 or 11)
                        p <= p;
                    end
                endcase
                // Arithmetic right shift of the combined product and multiplier
                // For simplicity, shift p and multiplier together
                {p, multiplier} <= {p[15], p} + {multiplier[15], multiplier};
                // Shift right by 2 bits (since radix-4)
                // To perform radix-4, we shift by 2 bits each cycle
                // Shift p and multiplier right by 2 bits
                {p, multiplier} <= {p, multiplier} >> 2;
                ctr <= ctr - 1;
            end else begin
                // Finalize
                rdy <= 1'b1;
            end
        end
    end

    assign p = p; // Output the product
    assign rdy = rdy;
endmodule

