module multi_booth_8bit (p, rdy, clk, reset, a, b);
    input clk, reset;
    input [7:0] a, b;
    output reg [15:0] p;
    output reg rdy;

    reg [15:0] multiplier;     // Holds sign-extended 'a'
    reg [15:0] multiplicand;   // Holds sign-extended 'b'
    reg [4:0] count;           // Counts the number of cycles (max 8 for radix-4, but we use 16 iterations for simplicity)
    reg [15:0] temp;           // Temporary register for partial sum
    reg [1:0] booth_code;      // Booth encoding bits
    reg [15:0] add_operand;    // Operand to add based on Booth code

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize all registers
            p <= 16'b0;
            rdy <= 0;
            multiplier <= {a[7], a}; // Sign-extend 8-bit to 16-bit
            multiplicand <= {b[7], b}; // Sign-extend 8-bit to 16-bit
            count <= 0;
            temp <= 0;
        end else begin
            if (count == 0) begin
                // Start of multiplication
                p <= 0;
                temp <= 0;
                // Prepare multiplier and multiplicand
                multiplier <= {a[7], a};
                multiplicand <= {b[7], b};
                count <= 0;
                rdy <= 0;
            end else if (count < 16) begin
                // Extract current two bits for Booth encoding
                // For Radix-4, bits are taken as [multiplier[2*count+1], multiplier[2*count]]
                // For simplicity, we process with overlapping bits by shifting
                // But since we're not using SystemVerilog, we manually handle bits

                // Calculate index for Booth bits
                // For iteration, bits are taken from multiplier
                // To handle boundary, assume zero padding
                reg [1:0] booth_bits;
                reg [2:0] bits_for_encoding;
                reg [15:0] shifted_multiplier;
                shifted_multiplier = multiplier;

                // Determine bits for current encoding
                // For simplicity, process bits with zero extension at the ends
                reg bit0, bit1, bit2;
                bit0 = (2*count < 16) ? multiplier[2*count] : 0;
                bit1 = (2*count + 1 < 16) ? multiplier[2*count + 1] : 0;
                bit2 = (2*count + 2 < 16) ? multiplier[2*count + 2] : 0;

                bits_for_encoding = {bit2, bit1, bit0};

                // Determine Booth code based on bits
                case (bits_for_encoding)
                    3'b000, 3'b111: begin
                        add_operand = 16'b0;
                    end
                    3'b001, 3'b010: begin
                        add_operand = multiplicand;
                    end
                    3'b011: begin
                        add_operand = multiplicand << 1;
                    end
                    3'b100: begin
                        add_operand = -(multiplicand << 1);
                    end
                    3'b101, 3'b110: begin
                        add_operand = -multiplicand;
                    end
                    default: begin
                        add_operand = 0;
                    end
                endcase

                // Shift the partial product
                // For Radix-4 Booth, each iteration adds or subtracts shifted multiplicand
                // The position depends on the iteration
                // So, add the operand shifted by 2*count bits
                p <= p + (add_operand <<< (2*count));

                // Shift multiplier for next iteration
                // For Radix-4, shift by 2 bits each iteration
                // But since we process bits directly, just move to next count
                count <= count + 1;
            end else begin
                // Completed all iterations
                rdy <= 1;
            end
        end
    end
endmodule

