                multiplier <= a_ext;
                multiplicand <= b_ext;
                product <= 0;
                count <= 1;
                rdy_reg <= 0;
            end else if (count <= 16) begin
                // Booth encoding based on current bits
                case (current_bits)
                    2'b01: begin
                        // Add multiplicand
                        product <= product + (multiplicand <<< (count - 1));
                    end
                    2'b10: begin
                        // Subtract multiplicand
                        product <= product - (multiplicand <<< (count - 1));
                    end
                    default: begin
                        // No operation
                        product <= product;
                    end
                endcase

                // Shift multiplier right by 2 bits for Radix-4
                // Since we are not using SystemVerilog, emulate shifting manually
                // But for simplicity, just proceed with count increment
                count <= count + 2; // Each iteration processes 2 bits
                if (count + 2 > 16) begin
                    // Finalize
                    rdy_reg <= 1;
                end
