                multiplier <= {a[7], a};
                multiplicand <= {b[7], b};
                count <= 1;
                rdy <= 0;
            end else if (count <= 8) begin
                // Booth algorithm iteration
                // Extract the last two bits of multiplier for encoding
                prev_bit <= multiplier[1:0];

                // Determine Booth code based on last two bits
                case (prev_bit)
                    2'b00, 2'b11: begin
                        // No operation, just shift
                        // do nothing
