module multi_booth_8bit (p, rdy, clk, reset, a, b);
    input clk, reset;
    input [7:0] a, b;
    output reg [15:0] p;
    output reg rdy;

    reg [15:0] multiplicand;
    reg [15:0] multiplier;
    reg [4:0] count; // 0 to 8 for Radix-4, but for 8-bit, 16 cycles needed
    reg [15:0] product;
    reg [1:0] booth_code;
    reg [7:0] a_ext, b_ext;

    // Sign-extend inputs to 16 bits
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            a_ext <= {a[7], a};
            b_ext <= {b[7], b};
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            p <= 16'b0;
            multiplier <= 16'b0;
            multiplicand <= 16'b0;
            count <= 5'd0;
            rdy <= 0;
            product <= 16'b0;
        end else begin
            if (count == 0) begin
                // Initialize for new multiplication
                p <= 16'b0;
                multiplier <= {a[7], a}; // sign-extended
                multiplicand <= {b[7], b}; // sign-extended
                count <= 16; // 16 cycles for 8-bit multiplication
                rdy <= 0;
            end else begin
                // Booth encoding based on two bits of multiplier
                // Examine LSB and the next bit (simulate radix-4)
                // For simplicity, process two bits at a time
                // Extract bits for Booth encoding
                // Since no break statements, process sequentially
                // Extract bits
                reg [1:0] booth_bits;
                booth_bits = multiplier[1:0];

                case (booth_bits)
                    2'b01: begin
                        // Add multiplicand
                        product = p + (multiplicand);
                    end
                    2'b10: begin
                        // Subtract multiplicand
                        product = p - (multiplicand);
                    end
                    2'b11: begin
                        // Subtract 2 * multiplicand
                        product = p - (multiplicand << 1);
                    end
                    default: begin
                        // 2'b00: do nothing
                        product = p;
                    end
                endcase

                p <= product;

                // Arithmetic right shift of multiplier and p
                {multiplier, p} <= {multiplier[15], multiplier[15:1]}, {p[15], p[15:1]};

                count <= count - 1;

                if (count == 1) begin
                    rdy <= 1;
                end
            end
        end
    end

    assign p = p;
    assign rdy = rdy;

endmodule

