module multi_booth_8bit (p, rdy, clk, reset, a, b);
    input clk, reset;
    input [7:0] a, b;
    output reg [15:0] p;
    output reg rdy;

    reg [15:0] multiplicand;
    reg [15:0] multiplier;
    reg [4:0] ctr; // 16 cycles, so 5 bits are enough
    reg [1:0] booth_bits; // to store current and previous bits if needed
    reg [15:0] temp;
    reg [15:0] partial_sum;

    // Internal signals for Booth decoding
    wire [1:0] current_bit;
    wire [1:0] prev_bit;

    // For Booth encoding, we need to look at current and previous bits
    reg prev_bit_reg;

    // Initialize registers
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            p <= 0;
            rdy <= 0;
            multiplier <= 0;
            multiplicand <= 0;
            ctr <= 0;
            prev_bit_reg <= 0;
        end else begin
            if (ctr == 0) begin
                // Load sign-extended inputs
                p <= 0;
                multiplier <= {a[7] ? 8'hFF : 8'h00, a};
                multiplicand <= {b[7] ? 8'hFF : 8'h00, b};
                rdy <= 0;
                ctr <= 16;
                prev_bit_reg <= 0;
            end else if (ctr > 0) begin
                // Booth encoding based on current and previous bits
                current_bit <= multiplier[0];
                prev_bit <= prev_bit_reg;

                case ({prev_bit, current_bit})
                    2'b01: begin
                        // Add multiplicand
                        p <= p + (multiplicand << (16 - ctr));
                    end
                    2'b10: begin
                        // Subtract multiplicand
                        p <= p - (multiplicand << (16 - ctr));
                    end
                    default: begin
                        // No operation
                        p <= p;
                    end
                endcase

                // Arithmetic right shift of multiplier and p
                {multiplier, prev_bit_reg} <= {multiplier[15], multiplier} >> 1;
                ctr <= ctr - 1;

                if (ctr == 1) begin
                    rdy <= 1;
                end
            end
        end
    end
