        assign partial_products[i] = (mul_b[i]) ? (mul_a << i) : {N{1'b0}};
    end
endgenerate

// First pipeline stage: sum partial products
wire [N+size-1:0] sum_stage1;
assign sum_stage1 = partial_products[0]
                    + (size > 1 ? partial_products[1] : 0)
                    + (size > 2 ? partial_products[2] : 0)
                    + (size > 3 ? partial_products[3] : 0);

// Since size=4, explicitly sum all partial products
wire [N+2:0] sum_all;
assign sum_all = partial_products[0]
                 + (size > 1 ? partial_products[1] : 0)
                 + (size > 2 ? partial_products[2] : 0)
                 + (size > 3 ? partial_products[3] : 0);

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        partial_sum_stage1 <= 0;
        partial_sum_stage2 <= 0;
        mul_out <= 0;
    end else begin
        // Store the first stage sum
        partial_sum_stage1 <= sum_all[N-1:0];
        // Second stage accumulates (here, only one addition needed)
        partial_sum_stage2 <= partial_sum_stage1;
        // Final product assignment
        mul_out <= partial_sum_stage2;
    end
end

endmodule

module multi_pipe_4bit#(
    parameter size = 4
)(
    input                       clk        ,   
    input                       rst_n      ,
    input   [size-1:0]          mul_a      ,
    input   [size-1:0]          mul_b      ,
    output  reg [size*2-1:0]    mul_out    
);

parameter N = 2 * size;

// Internal registers for pipeline stages
reg [size-1:0] a_reg1, a_reg2;
reg [size-1:0] b_reg1, b_reg2;

reg [size*2-1:0] partial_sum_stage1, partial_sum_stage2;
reg [size*2-1:0] partial_product [3:0]; // For partial products based on bits of mul_b

// Generate partial products based on bits of mul_b
wire [size-1:0] a_extended = mul_a;
wire [size-1:0] b_extended = mul_b;

// Stage 1: Generate partial products
// For each bit of mul_b, create shifted version of mul_a if bit is 1
wire [size*2-1:0] pp0 = (mul_b[0]) ? { {(size){1'b0}}, mul_a } : 0;
wire [size*2-1:0] pp1 = (mul_b[1]) ? { {(size-1){1'b0}}, mul_a, 1'b0 } : 0;
wire [size*2-1:0] pp2 = (mul_b[2]) ? { {(size-2){1'b0}}, mul_a, 2'b00 } : 0;
wire [size*2-1:0] pp3 = (mul_b[3]) ? { {(size-3){1'b0}}, mul_a, 3'b000 } : 0;

assign {partial_product[0], partial_product[1], partial_product[2], partial_product[3]} = {pp0, pp1, pp2, pp3};

// Sequential logic for pipeline registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_reg1 <= 0;
        a_reg2 <= 0;
        b_reg1 <= 0;
        b_reg2 <= 0;
        partial_sum_stage1 <= 0;
        partial_sum_stage2 <= 0;
        mul_out <= 0;
    end else begin
        // Pipeline register update
        a_reg1 <= mul_a;
        a_reg2 <= a_reg1; // Not strictly necessary, but for pipeline clarity
        b_reg1 <= mul_b;
        b_reg2 <= b_reg1;

        // Sum partial products in stages
        // Stage 1: sum of partial products
        partial_sum_stage1 <= partial_product[0] + partial_product[1];
        // Stage 2: add remaining partial products
        partial_sum_stage2 <= partial_sum_stage1 + partial_product[2] + partial_product[3];

        // Assign final product
        mul_out <= partial_sum_stage2;
    end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Stage 1: Generate partial products based on bits of mul_b
wire [size-1:0] partial_product [size-1:0];

genvar i;
generate
	for (i = 0; i < size; i = i + 1) begin : gen_partial
		assign partial_product[i] = (mul_b[i]) ? (mul_a << i) : {size{1'b0}};
	end
endgenerate

// Pipeline registers for partial sums
reg [N-1:0] sum_stage1 [size-1:0];
reg [N-1:0] sum_stage2 [size-1:0];

// Final sum register
reg [N-1:0] sum_final;

// Reset and pipeline logic
integer j;
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		for (j = 0; j < size; j = j + 1) begin
			sum_stage1[j] <= 0;
			sum_stage2[j] <= 0;
		end
		sum_final <= 0;
		mul_out <= 0;
	end else begin
		// Stage 1: load partial products into pipeline registers
		for (j = 0; j < size; j = j + 1) begin
			sum_stage1[j] <= partial_product[j];
		end

		// Stage 2: sum partial products
		reg [N-1:0] sum_acc;
		sum_acc = 0;
		for (j = 0; j < size; j = j + 1) begin
			sum_acc = sum_acc + sum_stage1[j];
		end
		for (j = 0; j < size; j = j + 1) begin
			sum_stage2[j] <= sum_stage1[j]; // propagate for pipeline
		end
		sum_final <= sum_acc;

		// Assign final product
		mul_out <= sum_acc;
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Stage 1: Generate partial products
wire [size-1:0] pp [size-1:0];

genvar i;
generate
	for (i = 0; i < size; i = i + 1) begin : gen_pp
		assign pp[i] = (mul_b[i]) ? (mul_a << i) : {size{1'b0}};
	end
endgenerate

// Pipeline registers for partial sums
reg [N-1:0] sum_stage1 [size-1:0]; // Store partial products
reg [N-1:0] sum_stage2 [size-1:0]; // Accumulated partial sums
reg [N-1:0] sum_final;

// Pipeline registers for partial products
reg [size-1:0] pp_reg [size-1:0];

integer j;

// Stage 1: Register partial products
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		for (j = 0; j < size; j = j + 1) begin
			pp_reg[j] <= 0;
		end
	end else begin
		for (j = 0; j < size; j = j + 1) begin
			pp_reg[j] <= pp[j];
		end
	end
end

// Stage 2: Accumulate partial products
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		for (j = 0; j < size; j = j + 1) begin
			sum_stage1[j] <= 0;
			sum_stage2[j] <= 0;
		end
		mul_out <= 0;
	end else begin
		// First partial product stored in sum_stage1
		for (j = 0; j < size; j = j + 1) begin
			sum_stage1[j] <= { (N - size){1'b0} , pp_reg[j] }; // Zero-extend to N bits
		end
		// Sequential addition for pipeline
		// For simplicity, sum all partial products in a ripple fashion
		// Initialize sum_final with the first partial product
		sum_final <= sum_stage1[0];
		// Add remaining partial products
		for (j = 1; j < size; j = j + 1) begin
			sum_final <= sum_final + { (N - size){1'b0} , pp_reg[j] };
		end
		mul_out <= sum_final;
	end
end

endmodule

module multi_pipe_8bit#(
    parameter size = 8
)(
    clk,
    rst_n,
    mul_a,
    mul_b,
    mul_en_in,
    mul_en_out,
    mul_out
);
    input clk;
    input rst_n;
    input mul_en_in;
    input [size-1:0] mul_a;
    input [size-1:0] mul_b;
    output reg mul_en_out;
    output reg [size*2-1:0] mul_out;

    reg [size-1:0] mul_a_reg, mul_b_reg;
    reg mul_en_out_reg;

    // Pipeline partial product wires
    wire [size*2-1:0] temp [0:7]; // 8 partial products

    // Generate partial products based on bits of mul_b
    assign temp[0] = (mul_b_reg[0]) ? {mul_a_reg, 8'b0} : 16'b0;
    assign temp[1] = (mul_b_reg[1]) ? ({mul_a_reg, 7'b0}) : 16'b0;
    assign temp[2] = (mul_b_reg[2]) ? ({mul_a_reg, 6'b0}) : 16'b0;
    assign temp[3] = (mul_b_reg[3]) ? ({mul_a_reg, 5'b0}) : 16'b0;
    assign temp[4] = (mul_b_reg[4]) ? ({mul_a_reg, 4'b0}) : 16'b0;
    assign temp[5] = (mul_b_reg[5]) ? ({mul_a_reg, 3'b0}) : 16'b0;
    assign temp[6] = (mul_b_reg[6]) ? ({mul_a_reg, 2'b0}) : 16'b0;
    assign temp[7] = (mul_b_reg[7]) ? ({mul_a_reg, 1'b0}) : 16'b0;

    // Registers to hold intermediate sums
    reg [size*2-1:0] sum_stage [0:7];

    // Final accumulation register
    reg [size*2-1:0] mul_out_reg;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers
            mul_a_reg <= 0;
            mul_b_reg <= 0;
            mul_en_out_reg <= 0;
            mul_out <= 0;
            mul_en_out <= 0;
            mul_out_reg <= 0;
            for (i=0; i<8; i=i+1) begin
                sum_stage[i] <= 0;
            end
        end else begin
            // Sample inputs
            if (mul_en_in) begin
                mul_a_reg <= mul_a;
                mul_b_reg <= mul_b;
            end
            mul_en_out_reg <= mul_en_in;

            // Stage 1: assign partial products
            // Already assigned via assign statements

            // Stage 2: sum partial products sequentially
            // sum_stage[0] = temp[0]
            sum_stage[0] <= temp[0];

            // sum_stage[1] = temp[1] + sum_stage[0]
            sum_stage[1] <= temp[1] + sum_stage[0];

            // sum_stage[2] = temp[2] + sum_stage[1]
            sum_stage[2] <= temp[2] + sum_stage[1];

            // sum_stage[3] = temp[3] + sum_stage[2]
            sum_stage[3] <= temp[3] + sum_stage[2];

            // sum_stage[4] = temp[4] + sum_stage[3]
            sum_stage[4] <= temp[4] + sum_stage[3];

            // sum_stage[5] = temp[5] + sum_stage[4]
            sum_stage[5] <= temp[5] + sum_stage[4];

            // sum_stage[6] = temp[6] + sum_stage[5]
            sum_stage[6] <= temp[6] + sum_stage[5];

            // sum_stage[7] = temp[7] + sum_stage[6]
            sum_stage[7] <= temp[7] + sum_stage[6];

            // Final product assignment
            // Store the last sum into mul_out in pipeline
            mul_out_reg <= sum_stage[7];

            // Output assignment
            mul_out <= mul_out_reg;
            mul_en_out <= mul_en_out_reg;
        end
    end
endmodule

module multi_pipe_8bit#(
    parameter size = 8
)(
    clk,
    rst_n,
    mul_a,
    mul_b,
    mul_en_in,
    mul_en_out,
