    output reg mul_en_out;
    output reg [size*2-1:0] mul_out;

    reg [size-1:0] mul_a_reg, mul_b_reg;
    reg mul_en_out_reg;

    // Partial products for each bit of mul_b
    wire [size-1:0] temp0, temp1, temp2, temp3, temp4, temp5, temp6, temp7;

    // Generate partial products based on bits of mul_b
    assign temp0 = (mul_b_reg[0]) ? mul_a_reg : 0;
    assign temp1 = (mul_b_reg[1]) ? (mul_a_reg << 1) : 0;
    assign temp2 = (mul_b_reg[2]) ? (mul_a_reg << 2) : 0;
    assign temp3 = (mul_b_reg[3]) ? (mul_a_reg << 3) : 0;
    assign temp4 = (mul_b_reg[4]) ? (mul_a_reg << 4) : 0;
    assign temp5 = (mul_b_reg[5]) ? (mul_a_reg << 5) : 0;
    assign temp6 = (mul_b_reg[6]) ? (mul_a_reg << 6) : 0;
    assign temp7 = (mul_b_reg[7]) ? (mul_a_reg << 7) : 0;

    // Pipeline registers for partial sums
    reg [size+7:0] sum_stage1, sum_stage2, sum_stage3, sum_stage4, sum_stage5, sum_stage6, sum_stage7, sum_final;
    reg [size*2-1:0] mul_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers
            mul_a_reg <= 0;
            mul_b_reg <= 0;
            mul_en_out <= 0;
            mul_out <= 0;
            mul_en_out_reg <= 0;
            sum_stage1 <= 0;
            sum_stage2 <= 0;
            sum_stage3 <= 0;
            sum_stage4 <= 0;
            sum_stage5 <= 0;
            sum_stage6 <= 0;
            sum_stage7 <= 0;
            sum_final <= 0;
            mul_out_reg <= 0;
        end else begin
            // Sample inputs
            if (mul_en_in) begin
                mul_a_reg <= mul_a;
                mul_b_reg <= mul_b;
            end
            mul_en_out <= mul_en_out_reg;

            // Stage 1: Generate partial products and first sum
            sum_stage1 <= {1'b0, temp0} + {1'b0, temp1};
            // Stage 2
            sum_stage2 <= sum_stage1 + {1'b0, temp2};
            // Stage 3
            sum_stage3 <= sum_stage2 + {1'b0, temp3};
            // Stage 4
            sum_stage4 <= sum_stage3 + {1'b0, temp4};
            // Stage 5
            sum_stage5 <= sum_stage4 + {1'b0, temp5};
            // Stage 6
            sum_stage6 <= sum_stage5 + {1'b0, temp6};
            // Stage 7
            sum_stage7 <= sum_stage6 + {1'b0, temp7};

            // Final stage: assign to output register
            // sum_stage7 is 16 bits, need to assign to mul_out_reg
            mul_out_reg <= sum_stage7;

            // Set output product
            mul_out <= mul_out_reg;

            // Delay enable signal to match pipeline
            mul_en_out_reg <= mul_en_in;
        end
    end
endmodule

module multi_pipe_8bit#(
    parameter size = 8
)(
    clk,
    rst_n,
    mul_a,
