    reg mul_en_out_reg;

    // Partial product wires
    wire [size-1:0] temp [size-1:0];

    // Registers for partial sums
    reg [size*2-1:0] sum0, sum1, sum2, sum3, sum4, sum5, sum6, sum7;

    // Final pipeline register for output
    reg [size*2-1:0] mul_out_reg;

    integer i;

    // Sample inputs
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_a_reg <= 0;
            mul_b_reg <= 0;
            mul_en_out <= 0;
        end else if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            mul_en_out <= 1;
        end else begin
            mul_en_out <= 0;
        end
    end

    // Generate partial products
    generate
        for (i = 0; i < size; i = i + 1) begin : gen_partial
            assign temp[i] = (mul_b_reg[i]) ? (mul_a_reg) : {size{1'b0}};
        end
    endgenerate

    // Pipeline stage 1: partial products shifted
    wire [size*2-1:0] pp0 = {{(size){1'b0}}, temp[0]};
    wire [size*2-1:0] pp1 = {{(size-1){1'b0}}, temp[1], 1'b0};
    wire [size*2-1:0] pp2 = {{(size-2){1'b0}}, temp[2], 2'b00};
    wire [size*2-1:0] pp3 = {{(size-3){1'b0}}, temp[3], 3'b000};
    wire [size*2-1:0] pp4 = {{(size-4){1'b0}}, temp[4], 4'b0000};
    wire [size*2-1:0] pp5 = {{(size-5){1'b0}}, temp[5], 5'b00000};
    wire [size*2-1:0] pp6 = {{(size-6){1'b0}}, temp[6], 6'b000000};
    wire [size*2-1:0] pp7 = {{(size-7){1'b0}}, temp[7], 7'b0000000};

    // First addition stage
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum0 <= 0;
            sum1 <= 0;
        end else if (mul_en_out) begin
            sum0 <= pp0 + pp1;
            sum1 <= pp2 + pp3;
        end
    end

    // Second addition stage
    reg [size*2-1:0] sum2, sum3;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum2 <= 0;
            sum3 <= 0;
        end else if (mul_en_out) begin
            sum2 <= sum0 + sum1;
            sum3 <= pp4 + pp5;
        end
    end

    // Third addition stage
    reg [size*2-1:0] sum4, sum5;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum4 <= 0;
            sum5 <= 0;
        end else if (mul_en_out) begin
            sum4 <= sum2 + sum3;
            sum5 <= pp6 + pp7;
        end
    end

    // Final sum
    reg [size*2-1:0] sum6;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum6 <= 0;
        end else if (mul_en_out) begin
            sum6 <= sum4 + sum5;
        end
    end

    // Final product assignment
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out_reg <= 0;
        end else if (mul_en_out) begin
            mul_out_reg <= sum6;
        end
    end

    // Output assignment
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out <= 0;
            mul_en_out <= 0;
        end else begin
            mul_out <= mul_out_reg;
            mul_en_out <= mul_en_out;
        end
    end

endmodule

module multi_pipe_8bit#(
    parameter size = 8
)(
    clk,      
    rst_n,       
    mul_a,       
    mul_b, 
    mul_en_in,

    mul_en_out,      
    mul_out    
);
   input clk;           
   input rst_n; 
   input mul_en_in;      
   input [size-1:0] mul_a;       
   input [size-1:0] mul_b;       

   output reg mul_en_out;  
   output reg [size*2-1:0] mul_out;    

   // Internal registers for input data
   reg [size-1:0] mul_a_reg;
   reg [size-1:0] mul_b_reg;
   reg mul_en_out_reg;

   // Partial product wires
   wire [size-1:0] temp [0:size-1];

   // Pipeline partial sums
   reg [size*2-1:0] sum [0:size-1];

   // Final output register
   reg [size*2-1:0] mul_out_reg;

   integer i;

   // Sample inputs and enable
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           mul_a_reg <= 0;
           mul_b_reg <= 0;
           mul_en_out_reg <= 0;
       end else begin
           if (mul_en_in) begin
               mul_a_reg <= mul_a;
               mul_b_reg <= mul_b;
               mul_en_out_reg <= 1;
           end else begin
               mul_en_out_reg <= 0;
           end
       end
   end

   // Generate partial products
   genvar j;
   generate
       for (j = 0; j < size; j = j + 1) begin : partial_products
           assign temp[j] = (mul_b_reg[j]) ? (mul_a_reg << j) : 0;
       end
   endgenerate

   // Initialize the first sum with partial products
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           for (i = 0; i < size; i = i + 1) begin
               sum[i] <= 0;
           end
       end else if (mul_en_out_reg) begin
           for (i = 0; i < size; i = i + 1) begin
               sum[i] <= { (size*2){1'b0} }; // Initialize to zero
           end
           // Assign partial products to stage 0
           for (i = 0; i < size; i = i + 1) begin
               sum[i] <= { (size*2){1'b0} };
           end
       end
   end

   // Pipeline addition stages
   // Stage 1: add first two partial products
   reg [size*2-1:0] stage_sum [0:size-1];
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           for (i = 0; i < size; i = i + 1) begin
               stage_sum[i] <= 0;
           end
       end else if (mul_en_out_reg) begin
           stage_sum[0] <= temp[0];
           for (i = 1; i < size; i = i + 1) begin
               stage_sum[i] <= stage_sum[i-1] + temp[i];
           end
       end
   end

   // Final accumulation
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           mul_out_reg <= 0;
       end else if (mul_en_out_reg) begin
           mul_out_reg <= stage_sum[size-1];
       end
   end

   // Assign output signals
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           mul_en_out <= 0;
           mul_out <= 0;
       end else begin
           mul_en_out <= mul_en_out_reg;
