   // Generate partial products
   genvar j;
   generate
       for (j=0; j<size; j=j+1) begin : gen_partial_products
           assign temp[j] = (mul_b_reg[j]) ? mul_a_reg : {size{1'b0}};
       end
   endgenerate

   // First stage: assign partial products to sum registers
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           for (i=0; i<size; i=i+1) begin
               sum[i] <= 0;
           end
           mul_out <= 0;
           mul_out_reg <= 0;
       end else if (mul_en_out) begin
           // Initialize sums for each partial product shifted accordingly
           for (i=0; i<size; i=i+1) begin
               sum[i] <= {temp[i], i{1'b0}}; // shift by i
           end

           // Perform iterative additions to combine partial sums
           // Since no for loops with variable iteration in synthesizable code,
           // unroll addition for small size
           // For simplicity, sum partial products step-by-step

           // Stage 1: add sums pairwise
           reg [size*2-1:0] sum_level [0:size-1];

           // Initialize sum_level
           for (i=0; i<size; i=i+1) begin
               sum_level[i] = sum[i];
