                     + (size > 2 ? sum_level[2] : 0)
                     + (size > 3 ? sum_level[3] : 0)
                     + (size > 4 ? sum_level[4] : 0)
                     + (size > 5 ? sum_level[5] : 0)
                     + (size > 6 ? sum_level[6] : 0)
                     + (size > 7 ? sum_level[7] : 0);

