reg [3:0] data;         // Register to hold input data
reg valid_out_reg;      // Register for valid_out
reg dout_reg;           // Register for dout

// Assign outputs
assign valid_out = valid_out_reg;
assign dout = dout_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all registers
        cnt <= 2'b00;
        data <= 4'b0000;
        valid_out_reg <= 1'b0;
        dout_reg <= 1'b0;
    end else begin
        if (cnt == 2'b00) begin
            // Load new data at the start of the cycle
            data <= d;
            valid_out_reg <= 1'b0;
            cnt <= cnt + 1;
        end else if (cnt == 2'b11) begin
            // Output last bit, then prepare for next cycle
            dout_reg <= data[3]; // MSB as current output
            valid_out_reg <= 1'b1;
            cnt <= 2'b00;
        end else begin
            // Shift data left for next bit
            data <= {data[2:0], 1'b0};
            dout_reg <= data[3]; // Output current MSB
            valid_out_reg <= 1'b0;
            cnt <= cnt + 1;
        end
    end
