module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    // Internal registers to track previous states
    reg data_in_prev;
    reg [1:0] state;

    // State encoding
    localparam IDLE     = 2'b00;
    localparam RISE     = 2'b01;
    localparam FALL     = 2'b10;
    localparam PULSE    = 2'b11;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            // Reset internal signals
            data_in_prev <= 1'b0;
            state        <= IDLE;
            data_out     <= 1'b0;
        end else begin
            // Default output
            data_out <= 1'b0;

            case (state)
                IDLE: begin
                    if (data_in == 1'b1 && data_in_prev == 1'b0) begin
                        // Detected rising edge, move to RISE state
                        state <= RISE;
                    end
                end

                RISE: begin
                    if (data_in == 1'b0 && data_in_prev == 1'b1) begin
                        // Detected falling edge after rise, pulse detected
                        state <= PULSE;
                        data_out <= 1'b1; // Signal pulse
                    end else if (data_in == 1'b1 && data_in_prev == 1'b0) begin
                        // Still high, stay in RISE
                        state <= RISE;
                    end else if (data_in == 1'b0 && data_in_prev == 1'b0) begin
                        // No transition, back to IDLE
                        state <= IDLE;
                    end
                end

                PULSE: begin
                    // After signaling pulse, go back to IDLE
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                end
            endcase

            // Update previous data_in for next cycle
            data_in_prev <= data_in;
        end
    end

endmodule

