    output reg data_out
);

    // State encoding
    localparam IDLE      = 2'b00;
    localparam ONE_DET   = 2'b01;
    localparam TWO_DET   = 2'b10;
    localparam PULSE_END = 2'b11;

    reg [1:0] state, next_state;
    reg data_in_d1, data_in_d2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset internal registers and outputs
            state <= IDLE;
            data_in_d1 <= 1'b0;
            data_in_d2 <= 1'b0;
            data_out <= 1'b0;
        end else begin
            // Shift register for data_in to detect transitions
            data_in_d2 <= data_in_d1;
            data_in_d1 <= data_in;

            // State transition logic
            case (state)
                IDLE: begin
                    data_out <= 1'b0;
                    if ((data_in_d2 == 1'b0) && (data_in_d1 == 1'b0) && (data_in == 1'b1))
                        next_state <= ONE_DET; // Detected 0->1 transition
                    else
                        next_state <= IDLE;
                end

                ONE_DET: begin
                    if ((data_in_d2 == 1'b0) && (data_in_d1 == 1'b1) && (data_in == 1'b0))
                        next_state <= TWO_DET; // Detected 1->0 transition after 0->1
                    else if (data_in == 1'b1)
                        next_state <= ONE_DET; // Stay in ONE_DET if still high
                    else
                        next_state <= IDLE; // Reset if sequence breaks
                end

                TWO_DET: begin
                    // Sequence complete, generate pulse
                    data_out <= 1'b1;
                    next_state <= PULSE_END;
                end

                PULSE_END: begin
                    // After signaling pulse, reset to IDLE
                    data_out <= 1'b0;
                    if ((data_in_d2 == 1'b1) && (data_in_d1 == 1'b0) && (data_in == 1'b0))
                        next_state <= IDLE; // Wait for next sequence
                    else
                        next_state <= PULSE_END; // Remain in end state until sequence resets
                end

                default: begin
                    next_state <= IDLE;
                end
            endcase

            state <= next_state;
        end
    end

