                    if (data_in_d2 == 1'b0 && data_in_d1 == 1'b1 && data_in == 1'b0) begin
                        // Detected 1->0 transition after 0->1, pulse complete
                        next_state <= PULSE_END;
                    end else if (data_in == 1'b1) begin
                        // Still high, stay in RISE_DETECTED
                        next_state <= RISE_DETECTED;
                    end else begin
                        // Unexpected transition, reset to IDLE
                        next_state <= IDLE;
                    end
                end

                PULSE_END: begin
                    // Signal pulse detection
                    data_out <= 1'b1;
                    // After signaling, go back to IDLE
                    next_state <= IDLE;
                end

                default: begin
                    next_state <= IDLE;
                end
            endcase

            // Update current state
            state <= next_state;

            // Clear data_out unless in PULSE_END state
            if (state != PULSE_END) begin
                data_out <= 1'b0;
            end
        end
    end

endmodule

module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    // State definitions
    parameter IDLE = 2'b00;
    parameter STATE_0_TO_1 = 2'b01;
    parameter STATE_1_TO_0 = 2'b10;
    parameter PULSE_DETECTED = 2'b11;

    reg [1:0] state, next_state;
    reg prev_data_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            prev_data_in <= 1'b0;
            data_out <= 1'b0;
        end else begin
            // Update previous data_in
            prev_data_in <= data_in;

            // State transition logic
            case (state)
                IDLE: begin
                    if (~prev_data_in && data_in) begin
                        // Detected 0 -> 1 transition
                        state <= STATE_0_TO_1;
                    end
                end
                STATE_0_TO_1: begin
                    if (prev_data_in && ~data_in) begin
                        // Detected 1 -> 0 transition
                        state <= PULSE_DETECTED;
                        data_out <= 1'b1; // Pulse detected
                    end else if (prev_data_in && data_in) begin
                        // Remain in same state if still high, wait for 0
                        state <= STATE_0_TO_1;
                    end else if (~prev_data_in && data_in) begin
                        // Unexpected 0 -> 1 again, restart detection
                        state <= STATE_0_TO_1;
                    end else begin
                        // No valid transition, reset to IDLE
                        state <= IDLE;
                    end
                end
                PULSE_DETECTED: begin
                    // Reset output after one cycle
                    data_out <= 1'b0;
                    // Return to IDLE after pulse detection
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module pulse_detect(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    // State encoding
    parameter IDLE = 2'b00;
    parameter RISE_DETECTED = 2'b01;
    parameter FALL_DETECTED = 2'b10;
    parameter PULSE = 2'b11;

    reg [1:0] state, next_state;
    reg prev_data_in;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            prev_data_in <= 1'b0;
            data_out <= 1'b0;
        end else begin
            prev_data_in <= data_in;

            case (state)
                IDLE: begin
                    data_out <= 1'b0;
                    if (~prev_data_in && data_in) begin
                        // Detected 0 -> 1 transition
                        state <= RISE_DETECTED;
                    end else begin
                        state <= IDLE;
                    end
                end

                RISE_DETECTED: begin
                    if (prev_data_in && ~data_in) begin
                        // Detected 1 -> 0 transition after 0->1
                        state <= PULSE;
                        data_out <= 1'b1; // Pulse detected
                    end else if (~prev_data_in && data_in) begin
                        // Still in rising edge, stay in RISE_DETECTED
                        state <= RISE_DETECTED;
                    end else if (~prev_data_in && ~data_in) begin
                        // No valid transition, reset to IDLE
                        state <= IDLE;
                    end else begin
                        // Waiting for 1->0 transition
                        state <= RISE_DETECTED;
                    end
                end

                PULSE: begin
                    // Reset output after signaling
                    data_out <= 1'b0;
                    // Wait for next sequence
                    if (~prev_data_in && data_in) begin
                        // New 0->1 transition, start over
                        state <= RISE_DETECTED;
                    end else begin
                        state <= IDLE;
                    end
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    // Internal registers to hold previous states
    reg prev_data_in;
    reg [1:0] state; // State machine: 0 - Idle, 1 - Detected 0->1, 2 - Detected 1->0 (Pulse complete)

    // State encoding
    localparam IDLE = 2'b00;
    localparam RISE_DETECTED = 2'b01;
    localparam FALL_DETECTED = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            // Reset all registers
            prev_data_in <= 1'b0;
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            // Default data_out to 0; will set to 1 only upon pulse detection
            data_out <= 1'b0;

            case (state)
                IDLE: begin
                    // Wait for rising edge: 0 -> 1
                    if (prev_data_in == 1'b0 && data_in == 1'b1) begin
                        state <= RISE_DETECTED;
                    end
                end

                RISE_DETECTED: begin
                    // Wait for falling edge: 1 -> 0
                    if (prev_data_in == 1'b1 && data_in == 1'b0) begin
                        // Pulse detected: sequence 0->1->0
                        data_out <= 1'b1;
                        state <= IDLE;
                    end
                end

                default: begin
                    state <= IDLE;
                end
            end

            // Update previous data_in for next cycle
            prev_data_in <= data_in;
        end
    end

endmodule

module RAM (
	input clk,
	input rst_n,

	input write_en,
	input [7:0]write_addr,
	input [5:0]write_data,

	input read_en,
	input [7:0]read_addr,
	output reg [5:0]read_data
);

    // Internal register array representing the RAM
    reg [5:0] RAM [0:255];
    integer i;

    // Write operation logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset: Initialize all memory locations to zero
            for (i = 0; i < 256; i = i + 1) begin
                RAM[i] <= 6'b0;
            end
        end
        else if (write_en) begin
            // Write data to the specified address
            RAM[write_addr] <= write_data;
        end
    end

    // Read operation logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset: Clear read data
            read_data <= 6'b0;
        end
        else if (read_en) begin
            // Read data from the specified address
            read_data <= RAM[read_addr];
        end
        else begin
            // Clear read data if read enable is not active
            read_data <= 6'b0;
        end
    end

endmodule

