	input clk,
	input rst_n,
	input din_serial,
	input din_valid,
	output reg [7:0]dout_parallel,
	output reg dout_valid
);

reg [7:0] shift_reg;
reg [3:0] cnt;

wire load_done;

assign load_done = (cnt == 4'b1000);

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		shift_reg <= 8'b0;
		cnt <= 4'b0;
		dout_valid <= 1'b0;
	end else begin
		if (din_valid) begin
			shift_reg <= {shift_reg[6:0], din_serial};
			cnt <= cnt + 1'b1;
		end
		if (load_done) begin
			dout_parallel <= shift_reg;
			dout_valid <= 1'b1;
		end else begin
			dout_valid <= 1'b0;
		end
	end
end

endmodule

