always @(posedge clk_b or negedge brstn) begin
    if (!brstn) begin
        en_clap_one <= 1'b0;
        en_clap_two <= 1'b0;
        dataout_hold <= 4'b0;
    end else begin
        en_clap_one <= en_data_reg;
        en_clap_two <= en_clap_one;
        if (en_clap_two) begin
            dataout_hold <= data_reg;
        end
    end
end

// Assign the output
always @(*) begin
    if (en_clap_two) begin
        dataout = data_reg;
    end else begin
        dataout = dataout_hold;
    end
end

