    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
    );

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    reg overflow_flag;
    reg carry_flag;
    reg negative_flag;
    reg zero_flag;
    reg flag_reg;
    wire [4:0] shift_amount;

    wire signed [31:0] signed_a = a;
    wire signed [31:0] signed_b = b;

    // Determine shift amount based on operation
    assign shift_amount = (aluc == SLL || aluc == SLLV) ? a[4:0] : (aluc == SRL || aluc == SRLV || aluc == SRA || aluc == SRAV) ? a[4:0] : 5'b0;

    always @(*) begin
        // Default assignments
        overflow_flag = 1'b0;
        carry_flag = 1'b0;
        flag_reg = 1'b0;
        case (aluc)
            ADD: begin
                {carry_flag, res} = a + b;
                // signed overflow detection
                overflow_flag = (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
            end
            ADDU: begin
                {carry_flag, res} = a + b;
                overflow_flag = 1'b0;
            end
            SUB: begin
                {carry_flag, res} = a - b;
                // signed overflow detection
                overflow_flag = (a[31] & ~b[31] & ~res[31]) | (~a[31] & b[31] & res[31]);
            end
            SUBU: begin
                {carry_flag, res} = a - b;
                overflow_flag = 1'b0;
            end
            AND: begin
                res = a & b;
            end
            OR: begin
                res = a | b;
            end
            XOR: begin
                res = a ^ b;
            end
            NOR: begin
                res = ~(a | b);
            end
            SLT: begin
                res = (signed_a < signed_b) ? 32'd1 : 32'd0;
                flag_reg = 1'b1; // SLT uses flag
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                flag_reg = 1'b1; // SLTU uses flag
            end
            SLL: begin
                res = b << shift_amount;
            end
            SRL: begin
                res = b >> shift_amount;
            end
            SRA: begin
                res = signed_b >>> shift_amount;
            end
            SLLV: begin
                res = b << a[4:0];
            end
            SRLV: begin
                res = b >> a[4:0];
            end
            SRAV: begin
                res = signed_b >>> a[4:0];
            end
            LUI: begin
                res = {b[15:0], 16'b0};
            end
            default: begin
                res = 32'hz; // invalid operation
            end
        endcase
    end

    // Assign output result
    assign r = res;
    // Zero flag
    assign zero = (res == 32'b0);
    // Negative flag (sign bit)
    assign negative = res[31];
    // Carry flag
    assign carry = carry_flag;
    // Overflow flag
    assign overflow = overflow_flag;
    // Flag for SLT/SLTU
    assign flag = flag_reg;

endmodule

