module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] current_dividend;
reg [7:0] current_divisor;
reg [4:0] count; // To count up to 16 bits
reg [15:0] quotient;
reg [15:0] remainder;

// Initialize the division process
always @(*) begin
    current_dividend = A;
    current_divisor = B;
    quotient = 16'b0;
    count = 0;
    // Perform 16 iterations for each bit
    for (count = 0; count < 16; count = count + 1) begin
        // Shift left the current_dividend by 1
        current_dividend = {current_dividend[14:0], 1'b0};
        // Extract the top 8 bits for comparison
        if (current_dividend[15:8] >= current_divisor) begin
            // Set quotient bit (from MSB to LSB)
            quotient[15 - count] = 1'b1;
            // Subtract divisor from top 8 bits
            current_dividend[15:8] = current_dividend[15:8] - current_divisor;
        end else begin
            quotient[15 - count] = 1'b0;
        end
    end
end

assign result = quotient;
assign odd = {current_dividend[7:0], current_dividend[15:8]}; // Concatenate remainder and top bits
endmodule

