module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output wire [7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'd0,
              s1_red = 2'd1,
              s2_yellow = 2'd2,
              s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg [7:0] green_duration, yellow_duration, red_duration;

    reg p_red, p_yellow, p_green;

    // Assign clock output to monitor counter
    assign clock = cnt;

    // Initialize durations
    initial begin
        green_duration = 8'd50; // default green time
        yellow_duration = 8'd10; // yellow time
        red_duration = 8'd50; // red time
    end

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            state <= next_state;
            // Counter management
            if (state != next_state || cnt == 8'd0) begin
                // Reset counter on state change
                cnt <= 0;
            end else if (cnt < 255) begin
                cnt <= cnt + 1;
            end
        end
    end

    // Next state logic
    always @(*) begin
        // Default next state
        next_state = state;
        case (state)
            idle: begin
                // Start with green
                next_state = s3_green;
            end
            s3_green: begin
                if (cnt >= green_duration) begin
                    next_state = s2_yellow;
                end
            end
            s2_yellow: begin
                if (cnt >= yellow_duration) begin
                    next_state = s1_red;
                end
            end
            s1_red: begin
                if (cnt >= red_duration) begin
                    next_state = s3_green;
                end
            end
            default: next_state = idle;
        endcase
    end

    // Adjust durations based on pass_request
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            green_duration <= 8'd50;
            red_duration <= 8'd50;
        end else if (state == s3_green && pass_request) begin
            // If pedestrian requests pass, extend red duration
            red_duration <= 8'd70;
        end else if (state == s3_green && cnt >= green_duration) begin
            // Reset red duration after transition
            red_duration <= 8'd50;
        end
    end

    // Output control
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                s3_green: begin
                    p_green <= 1;
                    p_yellow <= 0;
                    p_red <= 0;
                end
                s2_yellow: begin
                    p_green <= 0;
                    p_yellow <= 1;
                    p_red <= 0;
                end
                s1_red: begin
                    p_green <= 0;
                    p_yellow <= 0;
                    p_red <= 1;
                end
                default: begin
                    p_green <= 0;
                    p_yellow <= 0;
                    p_red <= 0;
                end
            endcase
        end
    end

    // Assign outputs
    always @(*) begin
        red = p_red;
        yellow = p_yellow;
        green = p_green;
    end

