    end

    // Next state logic
    always @(*) begin
        case (state)
            idle: begin
                // Initialize to green
                next_state = s3_green;
            end
            s1_red: begin
                if (cnt == 8'd0)
                    next_state = s2_yellow;
                else
                    next_state = s1_red;
            end
            s2_yellow: begin
                if (cnt == 8'd0)
                    next_state = s3_green;
                else
                    next_state = s2_yellow;
