    always @(*) begin
        case (state)
            s1_red: begin
                p_red = 1'b1;
                p_yellow = 1'b0;
                p_green = 1'b0;
            end
            s2_yellow: begin
                p_red = 1'b0;
                p_yellow = 1'b1;
