            default: begin
                p_red = 1'b0;
                p_yellow = 1'b0;
                p_green = 1'b0;
            end
        endcase
    end

    // Counter management
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd0;
        end else begin
            // Reset counter at state transition
            if (state != next_state) begin
                case (next_state)
                    s1_red: cnt <= 8'd50;        // Red duration
                    s2_yellow: cnt <= 8'd10;     // Yellow duration
                    s3_green: begin
                        if (pass_request)
                            cnt <= 8'd20;        // Shorter green if pedestrian requested
                        else
                            cnt <= 8'd60;        // Normal green duration
                    end
                    default: cnt <= 8'd0;
                endcase
            end else if (cnt != 8'd0) begin
                cnt <= cnt - 8'd1;
            end
        end
    end

    // Assign counter to output
    assign clock = cnt;

