module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output wire [7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'd0,
              s1_red = 2'd1,
              s2_yellow = 2'd2,
              s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg [7:0] green_duration;
    reg [7:0] yellow_duration;
    reg [7:0] red_duration;

    wire pass_req;

    // Initialize durations
    initial begin
        green_duration = 8'd50; // default green duration
        yellow_duration = 8'd10; // yellow duration
        red_duration = 8'd50; // default red duration
    end

    // Pass request signal
    assign pass_req = pass_request;

    // Continuous assignment for clock output
    assign clock = cnt;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            idle: begin
                next_state = s3_green;
            end
            s3_green: begin
                if (cnt >= green_duration) begin
                    next_state = s2_yellow;
                end else begin
                    next_state = s3_green;
                end
            end
            s2_yellow: begin
                if (cnt >= yellow_duration) begin
                    next_state = s1_red;
                end else begin
                    next_state = s2_yellow;
                end
            end
            s1_red: begin
                if (cnt >= red_duration) begin
                    next_state = s3_green;
                end else begin
                    next_state = s1_red;
                end
            end
            default: next_state = idle;
        endcase
    end

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd0;
        end else begin
            // Reset counter at each state change
            if ( (state != next_state) ) begin
                cnt <= 8'd0;
            end else begin
                // Increment counter
                if ( (state == s3_green && cnt < green_duration) ||
                     (state == s2_yellow && cnt < yellow_duration) ||
                     (state == s1_red && cnt < red_duration) ) begin
                    cnt <= cnt + 1;
                end
            end
        end
    end

    // Adjust green duration based on pass request
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            green_duration <= 8'd50;
        end else if (state == s3_green && pass_req && cnt == green_duration) begin
            // Shorten green if pass request received near end
            green_duration <= 8'd20;
        end else if (state == s3_green && cnt == green_duration) begin
            // Reset to default after adjustment
            green_duration <= 8'd50;
        end
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            case (state)
                s3_green: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b1;
                end
                s2_yellow: begin
                    red <= 1'b0;
                    yellow <= 1'b1;
                    green <= 1'b0;
                end
                s1_red: begin
                    red <= 1'b1;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
                default: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
            endcase
        end
    end

endmodule

